  if confirm "Did you find it there?"; then seen="yes: sync is still on"; else seen=no; fi
  if confirm "Did you see older synced CLI sessions there?"; then
    note "Turning sync off may not delete them; delete them on github.com if you don't want them kept."
    seen="$seen; older synced sessions present"
  fi
  record "30-copilot-cli" "## Copilot CLI sync check

Captured by agentsview: ${sid:-no}. Test session found on github.com: $seen.
"
  pause "Press Enter to go on"
}

s_mcp() {
  local target key sid n reg found stray
  say "Codex queries agentsview over MCP, through the unit (--server), for another agent's session (§9 item 3)."
  for key in cursor vscode; do
    sid="SID_$key"
    if [[ -n ${!sid:-} ]]; then
      target=$key
      break
    fi
  done
  if [[ -z ${target:-} ]]; then
    warn "neither the Cursor nor the VS Code session was captured, so there's nothing to look up"
    return 1
  fi
  sid="SID_$target" && sid=${!sid}
  n="NONCE_${target}_0" && n=${!n}
  if ! command -v codex >/dev/null 2>&1; then
    warn "Codex CLI (codex) isn't installed"
    return 1
  fi
  if codex mcp get agentsview >/dev/null 2>&1; then
    say "Codex already has an agentsview MCP server:"
    codex mcp get agentsview 2>/dev/null | sed 's/^/    /'
    reg=existing
  elif confirm "Register it in Codex: codex mcp add agentsview -- $BIN mcp --profile memory --server $API ?"; then
    codex mcp add agentsview -- "$BIN" mcp --profile memory --server "$API" || return 1
    reg=added
  else
    return 1
  fi
  step "In a new terminal: cd $SCRATCH_DIR && codex, then send:"
  prompt "Use the agentsview MCP server's search_content tool to find the conversation that contains $n. Tell me its session id and which agent it came from. Don't read files or run commands."
  say "Expected: $sid"
  if confirm "Did Codex find that session through the agentsview tool?"; then found=yes; else found=no; fi
  stray=$(stray_daemons)
  [[ -z $stray ]] || warn "agentsview running outside the unit: $stray"
  record "40-mcp" "## MCP from Codex

Registration ($reg): \`codex mcp add agentsview -- agentsview mcp --profile memory --server $API\`.
Codex found the $target session through it: $found. agentsview processes outside the unit afterwards: ${stray:-none}.
"
  pause "Press Enter to go on"
}

s_cursor_closed() {
  local db=$HOME/.config/Cursor/User/globalStorage/state.vscdb files rc py p
  if [[ ${CURSOR_DB_MODE:-} != wal ]]; then
    say "Cursor's database isn't in WAL mode (${CURSOR_DB_MODE:-not found}), so there's nothing to check."
    record "50-cursor-closed" "## Cursor database with Cursor closed

Not needed: journal mode ${CURSOR_DB_MODE:-not found}.
"
    pause "Press Enter to go on"
    return 0
  fi
  say "In WAL mode a read-only reader needs the -shm file. With Cursor running it exists; with Cursor"
  say "closed it may not, and the sandbox can't create it under a read-only home (§4.1)."
  step "Quit Cursor completely (every window)."
  pause "Press Enter when it has quit"
  files=""
  for p in "$db-wal" "$db-shm"; do [[ -e $p ]] && files+="${p##*/} "; done
  say "WAL files left: ${files:-none}"
  py="import sqlite3, sys; c = sqlite3.connect('file:' + sys.argv[1] + '?mode=ro', uri=True); print(c.execute('select count(*) from sqlite_master').fetchone()[0])"
  if [[ $UNIT_MODE == user ]]; then
    systemd-run --user --wait --quiet --collect "${SANDBOX_PROPS[@]}" "$(command -v python3)" -c "$py" "$db" >/dev/null 2>&1 && rc=0 || rc=$?
  else
    step "Run this in another terminal (opens the database read-only, sandboxed, as you):"
    prompt "sudo systemd-run --wait --quiet --collect --uid=$USER $(printf '%q ' "${SANDBOX_PROPS[@]}") $(command -v python3) -c \"$py\" $db; echo \"exit=\$?\""
    ask CURSOR_RO_EXIT "Exit code it printed:" || true
    rc=${CURSOR_RO_EXIT:-?}
  fi
  say "read-only open with Cursor closed: $([[ $rc == 0 ]] && echo works || echo "fails (exit $rc)")"
  record "50-cursor-closed" "## Cursor database with Cursor closed

WAL files left after quitting Cursor: ${files:-none}. Sandboxed read-only open: $([[ $rc == 0 ]] && echo works || echo "fails (exit $rc)").
"
  pause "Press Enter to go on"
}

s_bench() {
  local v dir tgz missing devices m repo file sha path backend name out table="" setvars=/opt/intel/oneapi/setvars.sh
  local -A ready=()
  say "llama-bench of Gemma 4 E2B, E4B and 26B-A4B on SYCL and on Vulkan (§9 item 5)."
  say "Downloads two llama.cpp builds (~90 MB) and three models (~25 GB) to $MODELS_DIR,"
  say "then benchmarks for roughly 30–60 minutes. Close other GPU-heavy apps first."
  if ! confirm "Run it now? (No: it's recorded as not run; re-run the wizard to do it later)"; then
    record "60-bench" "## GPU benchmark

Not run yet. Devices:
"
    return 1
  fi
  for v in sycl-fp16 vulkan; do
    dir=$SPIKE_DIR/llama/$LLAMA_BUILD-$v
    if [[ ! -x $dir/llama-bench ]]; then
      tgz=$(mktemp)
      curl -fL --retry 3 -o "$tgz" "https://github.com/ggml-org/llama.cpp/releases/download/$LLAMA_BUILD/llama-$LLAMA_BUILD-bin-ubuntu-$v-x64.tar.gz" || return 1
      if [[ $(sha256sum "$tgz" | cut -d' ' -f1) != "${LLAMA_SHA[$v]}" ]]; then
        warn "llama.cpp $v: SHA-256 mismatch"
        rm -f "$tgz"
        return 1
      fi
      mkdir -p "$dir" && tar -xzf "$tgz" -C "$dir" --strip-components=1 && rm -f "$tgz"
    fi
    missing=$(ldd "$dir/llama-bench" 2>/dev/null | awk '/not found/ { print $1 }' | paste -sd ' ' - || true)
    if [[ -n $missing && $v == sycl-fp16 && -f $setvars ]]; then
      # shellcheck disable=SC1090
      missing=$(bash -c "source $setvars >/dev/null 2>&1; ldd $dir/llama-bench" 2>/dev/null | awk '/not found/ { print $1 }' | paste -sd ' ' - || true)
    fi
    if [[ -n $missing ]]; then
      warn "$v: missing libraries: $missing"
      [[ $v == sycl-fp16 ]] && say "The SYCL build needs Intel's oneAPI runtime (DPC++, MKL, oneDNN, TBB) and the GPU's Level Zero driver."
      [[ $v == sycl-fp16 ]] && open_url "https://github.com/ggml-org/llama.cpp/blob/master/docs/backend/SYCL.md"
      record "61-bench-$v" "- $v: not run, missing libraries: $missing"
      continue
    fi
    devices=$(run_llama "$v" "$dir/llama-bench" --list-devices 2>&1 | awk '/Available devices/ { on = 1; next } on && NF' | sed 's/^ *//' | paste -sd ';' - || true)
    say "$v devices: ${devices:-none}"
    if [[ -z $devices || $devices == "(none)" ]]; then
      record "61-bench-$v" "- $v: not run, no device found"
      continue
    fi
    ready[$v]=$dir
    record "61-bench-$v" "- $v: $devices"
  done
  ((${#ready[@]})) || {
    warn "no backend can run here"
    return 1
  }
  mkdir -p "$MODELS_DIR" "$SPIKE_DIR/bench"
  for m in "${MODELS[@]}"; do
    read -r repo file sha <<<"$m"
    path=$MODELS_DIR/$file
    if [[ -f $path ]] && [[ $(sha256sum "$path" | cut -d' ' -f1) == "$sha" ]]; then continue; fi
    say "downloading $file…"
    curl -fL --retry 3 -C - -o "$path.part" "https://huggingface.co/$repo/resolve/main/$file" || return 1
    if [[ $(sha256sum "$path.part" | cut -d' ' -f1) != "$sha" ]]; then
      warn "$file: SHA-256 mismatch"
      rm -f "$path.part"
      return 1
    fi
    mv "$path.part" "$path"
  done
  for backend in "${!ready[@]}"; do
    for m in "${MODELS[@]}"; do
      read -r repo file sha <<<"$m"
      name=${file%.gguf}
      out=$SPIKE_DIR/bench/$backend-$name.jsonl
      say "$backend · $name…"
      run_llama "$backend" "${ready[$backend]}/llama-bench" -m "$MODELS_DIR/$file" -ngl 99 -p 512,2048 -n 128 -r 3 -o jsonl \
        >"$out" 2>"$out.err" || warn "$backend · $name failed: $(tail -1 "$out.err")"
      table+=$(jq -rs --arg b "$backend" --arg m "$name" '
        (map(select(.n_gen == 0 and .n_prompt == 512))[0].avg_ts // null) as $pp512 |
        (map(select(.n_gen == 0 and .n_prompt == 2048))[0].avg_ts // null) as $pp2048 |
        (map(select(.n_prompt == 0 and .n_gen == 128))[0].avg_ts // null) as $tg |
        "| \($m) | \($b) | \($pp512 // "-" | if type == "number" then . * 10 | round / 10 else . end) | \($pp2048 // "-" | if type == "number" then . * 10 | round / 10 else . end) | \($tg // "-" | if type == "number" then . * 10 | round / 10 else . end) |"' "$out" 2>/dev/null || echo "| $name | $backend | failed | | |")$'\n'
    done
  done
  record "60-bench" "## GPU benchmark (§9 item 5)

llama.cpp $LLAMA_BUILD, \`llama-bench -ngl 99 -p 512,2048 -n 128 -r 3\`, tokens per second:

| Model | Backend | pp512 | pp2048 | tg128 |
|---|---|---|---|---|
$table
Raw results: \`$SPIKE_DIR/bench\`. Devices:
"
  say "results:"
  printf '%s' "$table" | sed 's/^/    /'
  pause "Press Enter to go on"
}

# run_llama BACKEND BIN ARGS...: SYCL runs with oneAPI's environment when it's installed.
run_llama() {
  local backend=$1
  shift
  if [[ $backend == sycl-fp16 && -f /opt/intel/oneapi/setvars.sh ]]; then
    ZES_ENABLE_SYSMAN=1 bash -c 'source /opt/intel/oneapi/setvars.sh >/dev/null 2>&1; exec "$@"' _ "$@"
  elif [[ $backend == sycl-fp16 ]]; then
    ZES_ENABLE_SYSMAN=1 "$@"
  else
    "$@"
  fi
}

s_results() {
  local k label lag watch row rows=""
  for k in cursor vscode codex; do
    case $k in cursor) label="Cursor IDE" ;; vscode) label="VS Code Copilot Chat" ;; codex) label="Codex CLI" ;; esac
    local c="CAPTURED_$k" l="LAG_$k" w="WATCH_$k" fc="FAILCMD_$k" fe="FAILEDIT_$k"
    lag=${!l:-} watch=${!w:-}
    if [[ ${!c:-} != yes ]]; then
      row="| $label | no | | | | | no-go |"
    else
      local verdict=go
      awk -v a="$lag" -v b="$watch" 'BEGIN { exit !(a ~ /^[0-9.]+$/ && a <= 10 && b ~ /^[0-9.]+$/ && b <= 10) }' || verdict="check lag"
      [[ ${!fc:-} == yes ]] || verdict="$verdict, check failures"
      row="| $label | yes | $lag s | $watch s | ${!fc:-no} | ${!fe:-no} | $verdict |"
    fi
    rows+=$row$'\n'
  done
  record "90-summary" "## Summary

| Agent | Captured | Max prompt → API | Max first watch event | Failing command | Failed edit | Suggested |
|---|---|---|---|---|---|---|
$rows
Suggested is mechanical (captured, both lags ≤ 10 s, failing command detected); the go/no-go per
agent and the GPU backend are decided with these results in the design review.
"
  say "Results: $SPIKE_DIR/results.md"
  say "Paste that file into the agent-fabric conversation. It has timings, counts and settings, no"
  say "session text. The recordings in $REC stay on this machine."
  printf '\n'
  sed 's/^/    /' "$SPIKE_DIR/results.d/90-summary.md"
  pause "Press Enter to finish"
}

run_wizard() {

TOTAL_STAGES=15

mkdir -p "$SPIKE_DIR" && chmod 700 "$SPIKE_DIR"
# shellcheck disable=SC1090
[[ -f $ENV_FILE ]] && source "$ENV_FILE"

banner "agent-fabric phase 0 spike"

run_stage 1 "Preflight" s_preflight
run_stage 2 "Copilot session sync off" s_copilot_sync
run_stage 3 "Install agentsview" s_install
run_stage 4 "Sandbox probes: user or system unit" s_probes
run_stage 5 "Credential files and Cursor's database" s_secrets
run_stage 6 "Start the sandboxed unit" s_unit
run_stage 7 "Scratch project" s_scratch
run_stage 8 "Cursor IDE session" s_cursor
run_stage 9 "VS Code Copilot Chat session" s_vscode
run_stage 10 "Codex session" s_codex
run_stage 11 "Copilot CLI: not synced to GitHub" s_copilot_cli
run_stage 12 "MCP from Codex" s_mcp
run_stage 13 "Cursor's database with Cursor closed" s_cursor_closed
run_stage 14 "GPU benchmark: SYCL vs Vulkan" s_bench
stage "Results"
s_results

finish
}

run_wizard "$@"; exit
